    </nav>
  </header>

  <div class="strip">
    <div style="display:flex;justify-content:space-between;align-items:center">
      <div>
        <div style="font-weight:800">Shop</div>
        <div class="small">Diluted blends, small ritual kits, and consult add-ons</div>
      </div>
      <div class="controls">
        <div class="small">View pricing as</div>
        <div id="pricingToggle" style="display:flex;gap:8px;align-items:center">
          <label style="font-size:13px;color:#6b6b6b">Per Item</label>
          <button id="toggleBtn" style="width:52px;height:28px;border-radius:20px;border:1px solid #ddd;background:#fff;cursor:pointer;position:relative">
