        </div>
        <div class="product" data-single="14" data-bundle="34">
          <h4>Sunny Lift Mist</h4>
          <p>Bergamot + sweet orange, 30ml mist.</p>
          <div class="price">$<span class="pval">14</span></div>
          <div style="margin-top:8px"><a href="book.html" style="text-decoration:none;padding:8px 10px;border-radius:8px;background:var(--accent);color:white">Add to cart</a></div>
        </div>
        <div class="product" data-single="12" data-bundle="30">
          <h4>Focus Pocket Roller</h4>
          <p>Peppermint + cedar, 5ml roller.</p>
          <div class="price">$<span class="pval">12</span></div>
          <div style="margin-top:8px"><a href="book.html" style="text-decoration:none;padding:8px 10px;border-radius:8px;background:var(--accent);color:white">Add to cart</a></div>
        </div>
