      <div>Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </div>
  </footer>

  <script>
    // Pricing toggle for shop - animates numbers
    (function(){
      const btn = document.getElementById('toggleBtn');
      const knob = document.getElementById('knob');
      let bundle = false;
      const products = Array.from(document.querySelectorAll('.product'));
      function animateVal(el, start, end, time=450){
        const s = +start, e = +end; const t0 = performance.now();
        function tick(now){
          const p = Math.min(1,(now-t0)/time);
          const v = Math.round(s + (e-s)*p);
          el.textContent = v;
          if(p<1) requestAnimationFrame(tick);
        }
        requestAnimationFrame(tick);
      }
      btn.addEventListener('click', ()=>{
        bundle = !bundle;
        knob.style.transform = bundle ? 'translateX(24px)' : 'translateX(0)';
        products.forEach(prod=>{
          const single = prod.dataset.single || '0';
          const pack = prod.dataset.bundle || '0';
          const target = bundle ? pack : single;
          const span = prod.querySelector('.pval');
          animateVal(span, span.textContent, target);
        });
      });
    })();
  </script>
